func _physics_process(delta: float) -> void:
	if state == State.DYING:
		retry_remaining -= delta
		# player._physics_process returns on its first line while disabled,
		# so it cannot resume. This only lets the death drawing animate.
		player.dying_tick += 1
		player.queue_redraw()
		queue_redraw()
		if retry_remaining <= 0:
			restart_attempt()
